import { Group, PlaneGeometry, MeshBasicMaterial, Mesh, DoubleSide } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // Apply scene position from config
  const scenePos = config.scenePosition || {};
  group.position.set(
    scenePos.x !== undefined ? scenePos.x : 0,
    scenePos.y !== undefined ? scenePos.y : 0,
    scenePos.z !== undefined ? scenePos.z : 0
  );

  // Apply rotation
  const rot = scenePos.rotationXYZ || [0, 0, 0];
  group.rotation.order = 'YXZ';
  group.rotation.x = rot[0];
  group.rotation.y = rot[1];
  group.rotation.z = rot[2];

  // Apply scale
  const scale = scenePos.scaleXYZ || [1, 1, 1];
  group.scale.set(scale[0], scale[1], scale[2]);

  // Create plane geometry
  // Atlas region 512x320 → 1.6:1 aspect ratio
  const geometry = new PlaneGeometry(1.6, 1.0);

  // Load texture
  let texture = null;
  if (config.imageUrl && ctx.textureLoader) {
    texture = ctx.textureLoader.load(config.imageUrl);
  }

  // Create material
  const material = new MeshBasicMaterial({
    map: texture || undefined,
    color: texture ? 0xffffff : 0xff2a38,
    transparent: true,
    side: DoubleSide,
    toneMapped: false
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) {
      texture.dispose();
    }
  };

  // Event handlers object
  group.userData.handlers = {
    onPointerOver: null,
    onClick: null,
    onPointerOut: null
  };

  return group;
}
